let seed = 20260407; const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
const pick = (a) => a[Math.floor(rnd() * a.length)]; const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1)); const chance = (p) => rnd() < p;
