function mkFamily(last, forcedGuardians) { const g1 = forcedGuardians?.[0] ?? mkUser(uniqueName(last), last); const g2 = forcedGuardians?.[1] ?? (chance(0.6) ? mkUser(uniqueName(last), last) : null); const fam = { last, guardians: [g1, g2].filter(Boolean), address: `${int(10, 980)} ${pick(STREETS)}`, kids: [] }; families.push(fam); for (const g of fam.guardians) mkMember(g.id, RL, "guardian"); return fam; }
function mkPlayer(fam, age, teamId, divisionId, opts = {}) { const first = opts.first ?? uniqueName(fam.last); const id = `p${pad(++pN).padStart(4, "0")}`; const p = { id, leagueId: RL, firstName: first, lastName: fam.last, displayName: first, birthDate: birthDateForLeagueAge(age), leagueAge: age, teamId, divisionId, jerseyNumber: int(1, 44), positions: pick([["1B", "P"], ["SS", "2B"], ["CF", "LF"], ["C", "3B"], ["RF", "1B"], ["P", "SS"], ["LF", "RF"], ["2B", "CF"]]), bats: chance(0.85) ? "R" : "L", throws: chance(0.9) ? "R" : "L", guardianUserIds: fam.guardians.map((g) => g.id), ageGroup: ageGroupFor(age), weeklyPracticeGoal: pick([1, 2, 2, 3]), goals: pick([["Make contact every at bat"], ["Catch 10 fly balls in a row"], ["Learn to backhand"], ["Throw strikes"], []]), createdAt: isoT(addDays(TODAY, -int(60, 400))), consents: { academyParticipation: true, achievementsSharing: chance(0.5) ? "team" : "private", photoConsent: chance(0.7), videoReview: chance(0.4), coachFeedbackVisible: true, updatedAt: isoT(addDays(TODAY, -int(20, 100))), byUserId: fam.guardians[0].id } }; players.push(p); fam.kids.push(p); return p; }
