    const asst = id === "t09" ? hannah : (rosterFams.find((f) => f.guardians[0].id !== head.id && f.guardians[0].id !== jordan.id)?.guardians[0] ?? mkUser(uniqueName(pick(LAST)), pick(LAST)));
